export const hasEnvVars =
  process.env.NEXT_PUBLIC_SUPABASE_URL &&
  process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;

// Code generated by Claude.
// Browser only. Shrinks a photo and re-encodes it as JPEG.
// Re-encoding through a canvas also removes EXIF data, including GPS location.
export async function resizeImage(file: File, maxSize = 1024): Promise<File> {
  const bitmap = await createImageBitmap(file); // applies the photo's rotation
  const scale = Math.min(1, maxSize / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(bitmap.width * scale);
  canvas.height = Math.round(bitmap.height * scale);
  canvas.getContext("2d")!.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  bitmap.close();

  const blob = await new Promise<Blob>((resolve, reject) =>
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error("Could not process image"))),
      "image/jpeg",
      0.85,
    ),
  );
  return new File([blob], "proof.jpg", { type: "image/jpeg" });
}
